(function(){const table=document.getElementById("performance-drivers");if(!table)return;table.querySelectorAll("tbody tr").forEach(row=>{Array.from(row.cells).slice(2).forEach(cell=>{if(cell.classList.contains("metric-three-lines"))return;const nodes=Array.from(cell.childNodes);const top=document.createElement("div"),middle=document.createElement("div"),bottom=document.createElement("div");top.className="metric-line-weight";middle.className="metric-line-value";bottom.className="metric-line-extra";const first=nodes.find(n=>n.nodeType===1||n.nodeType===3&&n.textContent.trim());if(first&&first.nodeType===1&&first.tagName==="DIV"&&first.textContent.trim().match(/^[0-9.]+%$/)){top.appendChild(first)}else if(first&&first.nodeType===1&&first.tagName==="DIV"&&first.style.color&&first.textContent.trim().endsWith("%")){top.appendChild(first)}const extra=nodes.find(n=>n.nodeType===1&&n.tagName==="DIV"&&n.textContent.trim().startsWith("Qty ="));if(extra)bottom.appendChild(extra);while(cell.firstChild)middle.appendChild(cell.firstChild);cell.append(top,middle,bottom);cell.classList.add("metric-three-lines")})})})();
